/**
 * pi-shepherd — no-fuss pi extension: subagents + herding pi agents in Herdr.
 *
 * Entry point only. Engine lives in src/core/ (discovery, lifecycle, Herdr,
 * registries, session persistence); the pi tool/command surface lives in
 * src/extension/. Bundled agents are in .agents/agents/.
 */

import type { ExtensionAPI, ExtensionCommandContext } from '@earendil-works/pi-coding-agent';
import { truncateToWidth, visibleWidth } from '@earendil-works/pi-tui';
import { discoverAgents } from './src/core/discovery.ts';
import {
  fieldnotesEnabled,
  initializeSessionSettings,
  loadSettings,
} from './src/core/config.ts';
import { openSettings } from './src/extension/settings-ui.ts';
import {
  doAction,
  registerShepherdTools,
  setPromptWatcherSessionActive,
  setTaskWatcherSessionActive,
  setStaleWaitSessionActive,
  setShepherdMessageSessionActive,
  type ShepherdArgs,
} from './src/extension/shepherd.ts';
import { manualSpawnArgs, parseShepherdCli, tokenizeCli } from './src/extension/cli.ts';
import { configureUnseenCompletionBridge } from './src/extension/unseen-completions.ts';
import { lifecycleRegistry, bindSessionOwner } from './src/runtimes/herdr/orchestration.ts';
import {
  shutdownPromptWatchers,
  shutdownTaskWatchers,
  shutdownStaleWaitMonitor,
} from './src/runtimes/herdr/lifecycle.ts';
import { resolveOrCreateParentArtifactSession } from './src/core/artifact-sessions.ts';
import { migrationNoticeOnce } from './src/core/migration.ts';
import {
  isHerdrAvailable,
  paneOwnedByCurrentSession,
  workingOrWaitingSubagents,
  activeTasksByPane,
  loadCreatedPanes,
  type HerdrAgentSummary,
} from './src/runtimes/herdr/herdr.ts';
import type { AgentTaskStatus } from './src/runtimes/herdr/orchestration.ts';

/**
 * Persistent "below the editor" status box listing the subagents currently
 * working (see tui.md Pattern 5 / widget-placement.ts). Polls the live herd
 * into a snapshot every ~1s, then renders a bordered box at the real
 * viewport width: one row per agent with a color-coded state icon and an
 * mm:ss elapsed timer — shaped after the pi-interactive-subagents "Subagents"
 * widget, but theme-driven rather than hard-coded ANSI hues. No-op when
 * Herdr isn't reachable or there is nothing working.
 */
interface WorkingSnapshotItem extends HerdrAgentSummary {
  /** Recorded pane creation time (registry), or undefined for untracked panes. */
  createdAt?: number;
  /** Wall-clock ms when this agent started its current walking streak. */
  walkStartMs?: number;
  /** The agent's open tracked task, if any (independent of the process state). */
  task?: AgentTaskStatus;
}

function registerSubagentStatusWidget(pi: ExtensionAPI): void {
  const POLL_MS = 1_000;

  pi.on('session_start', (_event, ctx) => {
    if (!ctx.hasUI) return;
    let snapshot: WorkingSnapshotItem[] = [];
    // Walk origins: wall-clock time each agent entered its current
    // "working" walk. Recorded on first observation and dropped once the
    // walk ends, so every walk starts at age zero (right edge) and restarts
    // from there if the agent goes working again later.
    const walkStarts = new Map<string, number>();

    const tick = (tui: { requestRender(): void }): void => {
      // Poll Herdr + the registry once per tick, not per render frame.
      // The created-panes registry is shared across all shepherd sessions;
      // only the panes owned by THIS session belong in this widget.
      const panes = loadCreatedPanes().filter(paneOwnedByCurrentSession);
      const createdAtById = new Map(panes.map(p => [p.paneId, p.createdAt]));
      const agents = workingOrWaitingSubagents();
      const tasksByPane = activeTasksByPane();
      const workingNow = new Set(agents.filter(s => s.state === 'working').map(s => s.paneId));
      const now = Date.now();
      for (const paneId of walkStarts.keys()) {
        if (!workingNow.has(paneId)) walkStarts.delete(paneId);
      }
      for (const paneId of workingNow) {
        if (!walkStarts.has(paneId)) walkStarts.set(paneId, now);
      }
      snapshot = agents.map(s => ({
        ...s,
        createdAt: createdAtById.get(s.paneId),
        walkStartMs: walkStarts.get(s.paneId),
        task: tasksByPane.get(s.paneId)?.task,
      }));
      tui.requestRender();
    };

    ctx.ui.setWidget(
      'pi-shepherd-working',
      (tui, theme) => {
        let sheepFrame = 0;
        tick(tui);
        const timer = setInterval(() => tick(tui), POLL_MS);
        const animationTimer = setInterval(() => {
          if (!snapshot.some(agent => agent.state === 'working')) return;
          // Keeps the spinner and the sheep (a pure function of wall-clock
          // age) re-rendering; the counter only feeds the spinner now.
          sheepFrame += 1;
          tui.requestRender();
        }, SHEEP_FRAME_MS);
        return {
          render: (width: number) =>
            snapshot.length > 0
              ? renderWorkingAgents(
                  snapshot,
                  theme,
                  width,
                  sheepFrame,
                  loadSettings(currentCwd()).emojiSheep
                )
              : [],
          invalidate: () => {
            // Theme changed: rows are re-derived from the live snapshot,
            // which the poll timer keeps fresh.
            tui.requestRender();
          },
          dispose: () => {
            clearInterval(timer);
            clearInterval(animationTimer);
          },
        };
      },
      { placement: 'belowEditor' }
    );
  });
}

/** Elapsed since pane creation, mm:ss (the created-panes registry is the time source). */
function formatElapsedMMSS(createdAt: number, now = Date.now()): string {
  const seconds = Math.max(0, Math.floor((now - createdAt) / 1000));
  const m = Math.floor(seconds / 60);
  const s = seconds % 60;
  return `${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`;
}

/** Nature-inspired semantic color for a Herdr state. */
function stateColor(state: string): string {
  switch (state) {
    case 'working':
    case 'done':
    case 'completed':
      return 'success';
    case 'waiting':
      return 'warning';
    case 'error':
      return 'error';
    default:
      return 'dim';
  }
}

// Teal accent (#2aa198) for the box border and working spinner. The pi theme
// has no teal semantic color, so this is a fixed truecolor ANSI hue.
const TEAL_ANSI = '\u001b[38;2;42;161;152m';
const RESET_ANSI = '\u001b[0m';

function teal(text: string): string {
  return `${TEAL_ANSI}${text}${RESET_ANSI}`;
}

/** Colored status icon per Herdr agent state (green Braille spinner, … waiting, ✗ error). */
function stateIcon(
  state: string,
  theme: { fg(color: string, text: string): string },
  frame = 0
): string {
  const color = stateColor(state);
  switch (state) {
    case 'working':
      // Teal spinner; the rest of the row stays neutral.
      return teal(WORKING_SPINNER_FRAMES[frame % WORKING_SPINNER_FRAMES.length] ?? '⠋');
    case 'waiting':
      return theme.fg(color, '…');
    case 'error':
      return theme.fg(color, '✗');
    case 'done':
    case 'completed':
      return theme.fg(color, '✓');
    default:
      return theme.fg(color, '○');
  }
}

// The sheep walks right-to-left through the available gap after the active
// agent name. It jumps back to the right edge after reaching the left edge; it
// never walks back to the right. The glyph itself is not mirrored because
// Unicode/terminals do not provide a portable way to transform an emoji.
const SHEEP_SPEED = 1;
const SHEEP_FRAME_MS = 500;
const WORKING_SPINNER_FRAMES = ['⠋', '⠙', '⠹', '⠸', '⠼', '⠴', '⠦', '⠧', '⠇', '⠏'];

/**
 * Sheep position for an agent's walk age. The position is a pure function of
 * the milliseconds since the walk started (no shared frame counter), so the
 * walk runs exactly one frame per SHEEP_FRAME_MS at any setting. Position
 * wraps against this agent's track width, so different track widths never
 * desync each other's rhythm. Age 0 starts at the right edge.
 */
function animatedSheep(
  ageMs: number,
  useEmoji: boolean,
  theme: { fg(color: string, text: string): string },
  trackSpan: number
): string {
  const glyph = useEmoji ? '🐑' : 'o';
  const cycleWidth = trackSpan + 1;
  const position =
    trackSpan -
    ((((Math.floor(ageMs / SHEEP_FRAME_MS) * SHEEP_SPEED) % cycleWidth) + cycleWidth) % cycleWidth);
  return `${' '.repeat(position + 1)}${theme.fg('text', glyph)}`;
}

/**
 * Bordered "working" box, one line per agent, shaped after the pi-interactive-
 * subagents widget:
 *
 *   ╭─ shepherd ────────── 2 working ─╮
 *   │ ⠋ 01:23  planner  🐑      working │
 *   │ … 00:47  worker            waiting │
 *   ╰───────────────────────────────────╯
 *
 * Left text (icon + elapsed + name) truncates; the right status label is
 * preserved and right-aligned, padding the row to full terminal width.
 */
function renderWorkingAgents(
  agents: WorkingSnapshotItem[],
  theme: {
    fg(color: string, text: string): string;
  },
  width: number,
  sheepFrame = 0,
  useEmoji = true
): string[] {
  const title = 'shepherd';
  // Process and task state are shown independently: a pane may be working
  // with a running task, or idle while its task waits on a required reply.
  const workingCount = agents.filter(agent => agent.state === 'working').length;
  const waitingCount = agents.filter(agent => agent.task?.state === 'waiting').length;
  const infoParts: string[] = [];
  if (workingCount > 0) infoParts.push(`${workingCount} working`);
  if (waitingCount > 0) infoParts.push(`${waitingCount} waiting`);
  if (infoParts.length === 0 && agents.length > 0) infoParts.push(`${agents.length} active`);
  const info = infoParts.join(' · ');

  const lines: string[] = [borderTop(title, info, width, theme)];

  for (const agent of agents) {
    const task = agent.task;
    const waitingOnReply = task?.state === 'waiting';
    // An idle process that owns a waiting task renders as "waiting", not idle:
    // the child is parked, not finished.
    const iconState = waitingOnReply ? 'waiting' : agent.state;
    const elapsed = agent.createdAt != null ? ` ${formatElapsedMMSS(agent.createdAt)}` : '';
    const icon = stateIcon(iconState, theme, sheepFrame);
    // Right side: the task state wins while the task is open (working process +
    // waiting task → "waiting"), stale episodes are flagged distinctly.
    let rightState = agent.state;
    if (task) rightState = task.state;
    if (waitingOnReply && task?.stale) rightState = 'waiting (stale)';
    const right = ` ${theme.fg('text', rightState)} `;
    const name = theme.fg('text', agent.name);
    // Left side: waiting rows surface the elapsed wait and the expected-reply
    // recipient so the operator sees what is being waited on.
    let detail = '';
    if (waitingOnReply && task) {
      const waitingMins = Math.floor((task.waitingMs ?? 0) / 60_000);
      detail = ` ⏳${waitingMins}m`;
      if (task.waitingRecipient) detail += ` ←${task.waitingRecipient}`;
    }
    const prefix = ` ${icon}${elapsed}  ${name}${detail}`;
    const sheepGlyph = useEmoji ? '🐑' : 'o';
    const sheepWidth = visibleWidth(theme.fg('text', sheepGlyph));
    const leftWidth = Math.max(0, width - 2 - visibleWidth(right));
    const trackSpan = leftWidth - visibleWidth(prefix) - sheepWidth - 1;
    const sheep =
      agent.state === 'working' && trackSpan >= 0 && agent.walkStartMs != null
        ? animatedSheep(Date.now() - agent.walkStartMs, useEmoji, theme, trackSpan)
        : '';
    const left = `${prefix}${sheep}`;
    lines.push(borderLine(left, right, width, theme));
  }

  lines.push(borderBottom(width, theme));
  return lines;
}

/** Bordered top line: ╭─ title ──── info ─╮ (all chars within `width`). */
function borderTop(
  title: string,
  info: string,
  width: number,
  theme: { fg(color: string, text: string): string }
): string {
  if (width <= 0) return '';
  if (width === 1) return teal('╭');
  const inner = Math.max(0, width - 2); // inside ╭ and ╮
  const titlePart = `─ ${title} `;
  const infoPart = ` ${info} ─`;
  const fillLen = Math.max(0, inner - titlePart.length - infoPart.length);
  const fill = '─'.repeat(fillLen);
  const content = `${titlePart}${fill}${infoPart}`.slice(0, inner).padEnd(inner, '─');
  return `${teal('╭')}${teal(content)}${teal('╮')}`;
}

/** Bordered bottom line: ╰──────────────────╯ */
function borderBottom(width: number, theme: { fg(color: string, text: string): string }): string {
  if (width <= 0) return '';
  if (width === 1) return teal('╰');
  const inner = Math.max(0, width - 2);
  return `${teal('╰')}${teal('─'.repeat(inner))}${teal('╯')}`;
}

/**
 * Bordered content line: │left          right│ — left truncates, right is
 * preserved and right-aligned, padded to fill `width` (both │ chars included).
 */
function borderLine(
  left: string,
  right: string,
  width: number,
  theme: { fg(color: string, text: string): string }
): string {
  if (width <= 0) return '';
  if (width === 1) return teal('│');
  const contentWidth = Math.max(0, width - 2); // space inside the two │ chars
  const rightVis = visibleWidth(right);

  // If the status label alone is too wide, keep it compact rather than
  // overflowing the terminal.
  if (rightVis >= contentWidth) {
    const truncRight = truncateToWidth(right, contentWidth);
    const rightPad = Math.max(0, contentWidth - visibleWidth(truncRight));
    return `${teal('│')}${theme.fg('muted', truncRight)}${' '.repeat(rightPad)}${teal('│')}`;
  }

  const maxLeft = Math.max(0, contentWidth - rightVis);
  const truncLeft = truncateToWidth(left, maxLeft);
  const leftVis = visibleWidth(truncLeft);
  const pad = Math.max(0, contentWidth - leftVis - rightVis);
  return `${teal('│')}${theme.fg('muted', truncLeft)}${' '.repeat(pad)}${theme.fg('muted', right)}${teal('│')}`;
}

function parentArtifactSessionForCommand(ctx: ExtensionCommandContext) {
  if (!fieldnotesEnabled()) return undefined;
  const parentPiSessionId = ctx.sessionManager?.getSessionId?.();
  if (!parentPiSessionId) return undefined;
  return resolveOrCreateParentArtifactSession({
    parentPiSessionId,
    parentSessionFile: ctx.sessionManager?.getSessionFile?.(),
    projectRoot: ctx.cwd,
  });
}

/**
 * Delegate a command invocation to doAction() — the shared core that also backs
 * the model-facing tools — and surface the result through notifications.
 * Error results map to error-level notifications; thrown errors are caught so
 * a failing action never escapes into an unhandled rejection.
 */
async function runCommandAction(args: ShepherdArgs, ctx: ExtensionCommandContext): Promise<void> {
  try {
    const result = await doAction(args, {
      cwd: ctx.cwd,
      model: ctx.model ? { provider: ctx.model.provider, id: ctx.model.id } : undefined,
      thinkingLevel: ctx.thinkingLevel,
      sessionManager: ctx.sessionManager as any,
      ui: ctx.ui,
      hasUI: true,
    });
    const text = result.content.find(c => c.type === 'text')?.text ?? '(no output)';
    const hasError =
      typeof result.details === 'object' && result.details !== null && 'error' in result.details;
    ctx.ui?.notify(text, hasError ? 'error' : 'info');
  } catch (error: any) {
    ctx.ui?.notify(`pi-shepherd: ${error?.message ?? error}`, 'error');
  }
}

/**
 * Cwd of the most recent pi session. Held in module scope because the
 * /shepherd command's argument-completion callback receives only the typed
 * prefix (no ExtensionCommandContext), and the status widget's render
 * closure lives inside registerSubagentStatusWidget() — outside the
 * export default body, so a local there would be unresolvable at render
 * time. Falls back to the process cwd until session_start fires.
 */
let activeSessionCwd: string | undefined;

function currentCwd(): string {
  return activeSessionCwd ?? process.cwd();
}

export default function (pi: ExtensionAPI) {
  pi.on('session_start', (_event, ctx) => {
    // One-time farewell notice for the old package name. Display-only: it
    // never wakes the model, and child sheep processes are skipped inside
    // migrationNoticeOnce().
    const notice = migrationNoticeOnce();
    if (notice && typeof pi.sendMessage === 'function') {
      try {
        pi.sendMessage(
          { customType: 'shepherd-migration-notice', content: notice, display: true },
          { deliverAs: 'followUp', triggerTurn: false }
        );
      } catch {
        /* best effort: marker is already consumed */
      }
    }
    setPromptWatcherSessionActive(true);
    setTaskWatcherSessionActive(true);
    setStaleWaitSessionActive(true);
    setShepherdMessageSessionActive(true);
    activeSessionCwd = ctx.cwd;
    // Fieldnotes are intentionally session-scoped. Persisted setting changes
    // are applied when the next parent pi session starts.
    initializeSessionSettings(ctx.cwd);
    // Advance the in-memory lifecycle namespace when pi switches parent
    // sessions. The extension module can survive a session switch, so labels
    // and opaque lifecycle ids must not leak across the boundary.
    const sessionId = ctx.sessionManager?.getSessionId?.();
    lifecycleRegistry.beginSession(sessionId);
    // Bind this session's identity so the panes it creates are tagged and the
    // widget/registry views are scoped to its own sheep.
    bindSessionOwner(sessionId);
  });
  pi.on('session_shutdown', (_event, _ctx) => {
    // Watchers are parent-session scoped. Stop timers and discard delivery
    // registrations, but leave prompts, child panes, result files, and notes
    // untouched for normal lifecycle retention.
    setPromptWatcherSessionActive(false);
    setTaskWatcherSessionActive(false);
    setStaleWaitSessionActive(false);
    setShepherdMessageSessionActive(false);
    shutdownPromptWatchers();
    shutdownTaskWatchers();
    shutdownStaleWaitMonitor();
    // Drop the binding on teardown so a reload/new-session cycle without a
    // fresh identity never attributes fresh panes to a stale session.
    bindSessionOwner(undefined);
  });

  // Launched workers load the user extension set too, but their only Shepherd
  // surface is the in-tab completion extension from shepherd-done.ts. Keep the
  // parent orchestrator's tools, command, settings UI, and widget out of worker
  // sessions; PI_SHEPHERD_SESSION is set by herdr.ts only for launched agents.
  if (process.env.PI_SHEPHERD_SESSION) return;

  // Tools for natural-language use.
  registerShepherdTools(pi);
  configureUnseenCompletionBridge(pi);
  registerSubagentStatusWidget(pi);

  pi.registerCommand('shepherd', {
    description:
      'pi-shepherd: (no args) settings menu | agents | herd | spawn | status | read | settings',
    // Keep completion aligned with the actions the command supports. Agent
    // names (and live handle ids for status) are discovered fresh so
    // user-defined agents and running agents are available here.
    getArgumentCompletions: prefix => {
      const parts = prefix.split(/\s+/);
      const action = parts[0] ?? '';
      const discoveredAgentNames = () =>
        (() => {
          const cwd = currentCwd();
          const s = loadSettings(cwd);
          return discoverAgents(cwd, s.agentScope, {
            includeBundled: s.includeBundledAgents,
          });
        })()
          .agents.filter(agent => agent.name.length > 0)
          .map(agent => ({ name: agent.name, description: agent.description }));
      const liveHandleIdPrefixes = () =>
        lifecycleRegistry
          .allAgents()
          .map(handle => handle.id)
          .filter(id => id.length > 0);
      if (parts.length <= 1 && !prefix.endsWith(' ')) {
        // Pi does not automatically invoke the completion provider again
        // after applying an argument completion. When the user types
        // `/shepherd spa`, show full `spawn <agent>` entries immediately
        // instead of requiring a second completion cycle after `spawn`.
        if (action.length >= 3 && 'spawn'.startsWith(action)) {
          const names = discoveredAgentNames();
          if (names.length > 0) {
            return names.map(agent => ({
              value: `spawn ${agent.name}`,
              label: `spawn ${agent.name}`,
              description: agent.description,
            }));
          }
        }
        if (action.length >= 3 && 'status'.startsWith(action)) {
          const targets = [...discoveredAgentNames().map(a => a.name), ...liveHandleIdPrefixes()];
          if (targets.length > 0) {
            return targets.map(target => ({
              value: `status ${target}`,
              label: `status ${target}`,
            }));
          }
        }
        if (action.length >= 3 && 'read'.startsWith(action)) {
          const targets = [...discoveredAgentNames().map(a => a.name), ...liveHandleIdPrefixes()];
          if (targets.length > 0) {
            return targets.map(target => ({ value: `read ${target}`, label: `read ${target}` }));
          }
        }
        const actions = ['agents', 'herd', 'spawn', 'status', 'read', 'settings'];
        const filtered = actions.filter(s => s.startsWith(action));
        return filtered.length > 0 ? filtered.map(value => ({ value, label: value })) : null;
      }
      if (action === 'spawn') {
        const agentPrefix = prefix.slice('spawn'.length).trim();
        const filtered = discoveredAgentNames()
          .map(agent => agent.name)
          .filter(name => name.startsWith(agentPrefix));
        // Command completion replaces the complete argument string, not just
        // the final token. Preserve the action or Enter turns `spawn scout`
        // into only `scout`.
        return filtered.length > 0
          ? filtered.map(value => ({ value: `spawn ${value}`, label: value }))
          : null;
      }
      if (action === 'status' || action === 'read') {
        const targetPrefix = prefix.slice(action.length).trim();
        const targets = [
          ...discoveredAgentNames().map(a => a.name),
          // A registered agent name is preferred over its handle id; the
          // parser resolves each to a handle through the live registry.
          ...liveHandleIdPrefixes(),
        ].filter(t => t.startsWith(targetPrefix));
        return targets.length > 0
          ? targets.map(value => ({ value: `${action} ${value}`, label: value }))
          : null;
      }
      return null;
    },
    handler: async (args, ctx: ExtensionCommandContext) => {
      const raw = (args ?? '').trim();
      // Quote-aware tokenization (shared with the CLI preview renderer) so
      // flags like --cwd="/a b" survive the split.
      let tokens = raw ? tokenizeCli(raw) : [];
      // With no arguments (or the explicit `settings` action), open the
      // settings menu — the command's default behavior.
      if (tokens.length === 0 || tokens[0] === 'settings') {
        await openSettings(ctx);
        return;
      }
      // Historical aliases remain accepted but are never offered in
      // completions; `agents` is canonical.
      if (tokens[0] === 'list' || tokens[0] === 'sheep') tokens = ['agents', ...tokens.slice(1)];
      const parsed = parseShepherdCli(tokens);
      if ('error' in parsed) {
        ctx.ui?.notify(`pi-shepherd: ${parsed.error}`, 'warning');
        return;
      }
      // Only `agents` is pure local discovery; everything else needs the
      // Herdr runtime, so warn with the setup hint instead of a raw error.
      if (parsed.action !== 'agents' && !isHerdrAvailable()) {
        ctx.ui?.notify(
          'pi-shepherd: Herdr runtime not reachable. Start Herdr with `herdr`, or run pi inside a Herdr pane.',
          'warning'
        );
        return;
      }
      if (parsed.action === 'spawn') {
        const agent = String(parsed.args.agent);
        ctx.ui?.setStatus?.('pi-shepherd', `Starting ${agent}…`);
        try {
          await runCommandAction(
            {
              // Manual spawn always means a separate agent (T012).
              ...manualSpawnArgs(parsed.args),
              // Pre-resolve tolerantly (undefined when fieldnotes are
              // disabled or no session identity exists); 'artifactSession'
              // in args makes doAction honor the explicit value instead of
              // requiring one.
              artifactSession: parentArtifactSessionForCommand(ctx),
            } as unknown as ShepherdArgs,
            ctx
          );
        } finally {
          ctx.ui?.setStatus?.('pi-shepherd', undefined);
        }
        return;
      }
      await runCommandAction(parsed.args as ShepherdArgs, ctx);
    },
  });
}

/**
 * Shared CLI grammar for pi-shepherd.
 *
 * One options table defines how a shepherd command is spelled as a line of
 * flags and positionals:
 *   - `parseShepherdCli` turns `/shepherd …` tokens into doAction args
 *     (the human command surface),
 *   - `formatShepherdCommand` renders doAction args back into the compact
 *     CLI-style text used by tool-call previews (the model surface).
 *
 * The two are the inverse of each other: they read and write the same
 * `OPTION_SPECS` table, so a rendered line always parses back to the same
 * args.
 */

import { resolve } from 'node:path';
import { lifecycleRegistry } from '../runtimes/herdr/orchestration.ts';

export const SCOPE_VALUES = ['user', 'project', 'both'] as const;
export const PLACEMENT_VALUES = ['pane_right', 'pane_down', 'tab', 'workspace'] as const;
export const SOURCE_VALUES = ['visible', 'recent', 'recent-unwrapped', 'detection'] as const;

interface OptionSpec {
  /** Canonical CLI flag name (without `--`). */
  flag: string;
  /** Extra accepted spellings for the human CLI. */
  aliases?: string[];
  /** doAction args key. */
  key: string;
  /** Restricted value set (validated, and used in error hints). */
  values?: readonly string[];
  /** Value must be an integer (coerced from string). */
  integer?: boolean;
  /** Value must be `true`/`false` (coerced to boolean). */
  boolean?: boolean;
  /** Bare flag: no value, always sets true. */
  bare?: boolean;
}

const OPTION_SPECS: Record<string, OptionSpec> = {
  // Scope remains available for `agents` discovery; it is intentionally not a
  // spawn option because spawn must use the persisted settings scope.
  agentScope: { flag: 'scope', aliases: ['agent-scope'], key: 'agentScope', values: SCOPE_VALUES },
  label: { flag: 'label', key: 'label' },
  placement: { flag: 'placement', key: 'placement', values: PLACEMENT_VALUES },
  no_parent: { flag: 'no-parent', key: 'no_parent', bare: true },
  cwd: { flag: 'cwd', key: 'cwd' },
  lines: { flag: 'lines', key: 'lines', integer: true },
  source: { flag: 'source', key: 'source', values: SOURCE_VALUES },
  timeout: { flag: 'timeout', key: 'timeout', integer: true },
};

const FLAG_LOOKUP = new Map<string, OptionSpec>();
for (const spec of Object.values(OPTION_SPECS)) {
  FLAG_LOOKUP.set(spec.flag, spec);
  for (const alias of spec.aliases ?? []) FLAG_LOOKUP.set(alias, spec);
}

// Which option keys each command verb accepts (renderer and parser agree).
const SPAWN_OPTION_KEYS = ['label', 'placement', 'no_parent', 'cwd'];
const READ_OPTION_KEYS = ['lines', 'source'];

const USAGE =
  'Usage: /shepherd <agents [user|project|both] | herd | spawn <agent> [options] | status <agent|id> | read <target> [options] | settings>\n' +
  '  spawn options: --label \"task label\", --placement pane_right|pane_down|tab|workspace, --no-parent, --cwd <path>\n' +
  '  read options: --lines <n>, --source ' +
  SOURCE_VALUES.join('|');

// ── Parsing ──────────────────────────────────────────────────────────────────

/**
 * Split a command line into tokens. The inverse of `formatShepherdCommand`'s
 * CLI quoting: whitespace separates tokens, and a `"` starts a quoted run that
 * is decoded as a JSON string (so `--cwd="/a b"` re-parses to the value `/a b`).
 * A quoted run may appear mid-token (e.g. immediately after `--cwd=`), so its
 * decoded value is appended to the surrounding token. Because `cliValue` wraps
 * values via `JSON.stringify`, every quoted run is a valid JSON string literal.
 */
export function tokenizeCli(input: string): string[] {
  const tokens: string[] = [];
  let cur = '';
  let i = 0;
  const push = () => {
    if (cur !== '') tokens.push(cur);
    cur = '';
  };
  while (i < input.length) {
    const c = input[i];
    if (c === '"') {
      // Capture one JSON string literal and decode it, appending to `cur`
      // so `--cwd=<quoted>` keeps the flag prefix attached.
      let j = i + 1;
      let body = '';
      while (j < input.length) {
        if (input[j] === '\\') {
          body += input[j] + (input[j + 1] ?? '');
          j += 2;
          continue;
        }
        if (input[j] === '"') break;
        body += input[j];
        j++;
      }
      try {
        cur += JSON.parse('"' + body + '"');
      } catch {
        cur += body; // malformed quote — keep the raw run rather than crashing
      }
      i = j + 1;
      continue;
    }
    if (c === ' ' || c === '\t') {
      push();
      i++;
      continue;
    }
    cur += c;
    i++;
  }
  push();
  return tokens;
}

export type ParsedShepherdCommand =
  | { action: 'agents'; args: Record<string, unknown> }
  | { action: 'herd'; args: Record<string, unknown> }
  | { action: 'spawn'; args: Record<string, unknown> }
  | { action: 'status'; args: Record<string, unknown> }
  | { action: 'read'; args: Record<string, unknown> };

export type ParseShepherdCliResult = ParsedShepherdCommand | { error: string };

/**
 * Parse `--flag value` / `--flag=value` / bare flags tokens into an options
 * object using the shared table. Non-`--` tokens are collected into
 * `positional` (the caller decides how many are allowed).
 */
function parseFlags(
  tokens: string[],
  from: number,
  allowed: readonly string[],
  positional: string[]
): { options: Record<string, unknown>; error?: string } {
  const allowedSet = new Set(allowed);
  const options: Record<string, unknown> = {};
  for (let i = from; i < tokens.length; i++) {
    const token = tokens[i];
    if (!token.startsWith('--')) {
      positional.push(token);
      continue;
    }
    const eq = token.indexOf('=');
    const flag = (eq >= 0 ? token.slice(0, eq) : token).replace(/^--/, '');
    const spec = FLAG_LOOKUP.get(flag);
    if (!spec || !allowedSet.has(spec.key))
      return { options, error: `Unknown option "--${flag}".` };
    if (spec.bare) {
      if (eq >= 0) return { options, error: `Option --${spec.flag} takes no value.` };
      options[spec.key] = true;
      continue;
    }
    const raw = eq >= 0 ? token.slice(eq + 1) : tokens[++i];
    if (raw === undefined || raw === '' || raw.startsWith('--'))
      return { options, error: `Missing value for --${spec.flag}.` };
    if (spec.values && !spec.values.includes(raw))
      return {
        options,
        error: `Invalid value "${raw}" for --${spec.flag}; use ${spec.values.join(', ')}.`,
      };
    if (spec.integer) {
      if (!/^-?\d+$/.test(raw))
        return { options, error: `Value "${raw}" for --${spec.flag} must be an integer.` };
      options[spec.key] = Number(raw);
    } else if (spec.boolean) {
      if (raw !== 'true' && raw !== 'false')
        return { options, error: `Value "${raw}" for --${spec.flag} must be true or false.` };
      options[spec.key] = raw === 'true';
    } else {
      options[spec.key] = raw;
    }
  }
  return { options };
}

/**
 * Resolve a human status target (agent name, lifecycle id, or pane id) to the
 * opaque lifecycle id the status action uses. Falls back to the supplied value
 * so the registry can return its useful unknown-id error.
 */
export function statusHandleTarget(target: string): string {
  for (const handle of lifecycleRegistry.allAgents()) {
    if (handle.id === target || handle.agent === target || handle.paneId === target) {
      return handle.id;
    }
  }
  return target;
}

/**
 * Parse the tokens of a `/shepherd` invocation into doAction args.
 * `settings` is command-only and handled by the caller before parsing.
 */
export function parseShepherdCli(tokens: string[]): ParseShepherdCliResult {
  const action = tokens[0] ?? '';

  if (action === 'herd') {
    if (tokens.length > 1) return { error: `/shepherd herd takes no arguments.\n${USAGE}` };
    return { action: 'herd', args: { action: 'herd' } };
  }

  if (action === 'agents') {
    // Scope may be a positional (`agents both`) or a flag (`agents --scope both`).
    const positional: string[] = [];
    const { options, error } = parseFlags(tokens, 1, ['agentScope'], positional);
    if (error) return { error: `${error}\n${USAGE}` };
    const positionalScope = positional[0];
    if (positional.length > 1 || (positionalScope && 'agentScope' in options))
      return {
        error: `/shepherd agents takes at most one scope argument (positional or --scope).\n${USAGE}`,
      };
    const scope = positionalScope ?? (options.agentScope as string | undefined);
    if (scope && !SCOPE_VALUES.includes(scope as 'user'))
      return { error: `Invalid scope "${scope}"; use ${SCOPE_VALUES.join(', ')}.` };
    return {
      action: 'agents',
      args: { action: 'agents', ...(scope ? { agentScope: scope } : {}) },
    };
  }

  if (action === 'spawn') {
    const positional: string[] = [];
    const { options, error } = parseFlags(tokens, 1, SPAWN_OPTION_KEYS, positional);
    if (error) return { error: `${error}\n${USAGE}` };
    const [agent, ...extra] = positional;
    if (!agent) return { error: `spawn requires an agent name.\n${USAGE}` };
    if (extra.length > 0) return { error: `Unexpected argument "${extra[0]}".\n${USAGE}` };
    return {
      action: 'spawn',
      args: { action: 'spawn', agent, label: options.label ?? '', ...options },
    };
  }

  if (action === 'status') {
    if (tokens.length > 2) return { error: `/shepherd status takes exactly one target.\n${USAGE}` };
    const target = tokens[1];
    if (!target) return { error: `status requires an agent name or lifecycle id.\n${USAGE}` };
    return { action: 'status', args: { action: 'status', id: statusHandleTarget(target) } };
  }

  if (action === 'read') {
    const positional: string[] = [];
    const { options, error } = parseFlags(tokens, 1, READ_OPTION_KEYS, positional);
    if (error) return { error: `${error}\n${USAGE}` };
    const [name, ...extra] = positional;
    if (!name)
      return { error: `read requires a target (agent name, pane id, or lifecycle id).\n${USAGE}` };
    if (extra.length > 0) return { error: `Unexpected argument "${extra[0]}".\n${USAGE}` };
    return { action: 'read', args: { action: 'read', name, ...options } };
  }

  if (tokens.length === 0)
    return {
      error: `Provide an action. Try: agents, herd, spawn <agent>, status <target>, read <target>, or settings.\n${USAGE}`,
    };
  return {
    error: `Unknown action "${action}". Try: agents, herd, spawn <agent>, status <target>, read <target>, or settings.\n${USAGE}`,
  };
}

// ── Rendering (inverse of the parser) ───────────────────────────────────────

/**
 * Manual `/shepherd spawn` means "give me a separate agent": on the Herdr
 * app / hc backend it always requests a parentless tab, regardless of any
 * default the parser or a tool transport materialized. The Herdr TUI backend
 * ignores the mode because every agent already has its own pane.
 */
export function manualSpawnArgs(args: Record<string, unknown>): Record<string, unknown> {
  return { ...args, no_parent: true };
}

/**
 * Tool transports may materialize optional spawn defaults before the renderer
 * sees them. Keep those implementation defaults out of user-facing text so a
 * required-only call still reads like a required-only call.
 */
export function omitMaterializedDefaults(
  verb: string,
  options: Record<string, any>,
  defaultCwd = process.cwd()
): Record<string, any> {
  const result = { ...options };
  if (verb !== 'spawn') return result;
  if (result.placement === 'tab') delete result.placement;
  if (typeof result.cwd === 'string' && resolve(result.cwd) === resolve(defaultCwd))
    delete result.cwd;
  return result;
}

/** Keep tool-call previews compact without rendering an empty placeholder. */
function previewText(value: unknown, maxLength = 40): string {
  const text = typeof value === 'string' ? value.replace(/\s+/g, ' ').trim() : String(value ?? '');
  return text.length > maxLength ? `${text.slice(0, maxLength)}…` : text;
}

/** Render opaque lifecycle ids as compact CLI-like values. */
function handlePreview(value: unknown, maxLength = 40): string {
  const rawId =
    typeof value === 'string'
      ? value
      : value && typeof value === 'object' && 'id' in value
        ? (value as any).id
        : undefined;
  if (typeof rawId === 'string') {
    try {
      const agent = lifecycleRegistry.getAgent(rawId);
      return previewText(
        `${agent.handle.agent}${agent.handle.label ? `: ${agent.handle.label}` : ''}`,
        maxLength
      );
    } catch {
      try {
        const prompt = lifecycleRegistry.getPrompt(rawId) as any;
        const agent = lifecycleRegistry.getAgent(prompt.handle.agentId);
        return previewText(
          `${agent.handle.agent}${agent.handle.label ? `: ${agent.handle.label}` : ''}`,
          maxLength
        );
      } catch {
        /* retain opaque id for unknown handles */
      }
    }
  }
  if (Array.isArray(value)) {
    return `[${value.map(item => handlePreview(item, maxLength)).join(', ')}]`;
  }

  if (value && typeof value === 'object' && 'id' in value) {
    return previewText((value as { id?: unknown }).id, maxLength);
  }

  // A few providers serialize nested legacy handle arguments before they reach the
  // renderer. Keep the display useful even though prepareArguments normalizes
  // them before execution.
  if (typeof value === 'string') {
    try {
      const parsed: unknown = JSON.parse(value);
      if (parsed && typeof parsed === 'object') return handlePreview(parsed, maxLength);
    } catch {
      // It may simply be an id, so fall through.
    }
  }

  return previewText(value, maxLength);
}

/** Quote values that would otherwise be ambiguous in a command-like preview. */
function cliValue(value: unknown, maxLength = 80): string {
  const text = previewText(value, maxLength);
  return /[\s"'=]/.test(text) ? JSON.stringify(text) : text;
}

function cliOption(key: string, value: unknown, maxLength = 80): string {
  if (value === undefined || value === null || value === '') return '';
  const spec = OPTION_SPECS[key];
  // Bare flags render without a value; `false` cannot be expressed as a bare
  // flag, so it is omitted (the schema default applies).
  if (spec.bare) return value ? `--${spec.flag}` : '';
  // Booleans render as `--flag=true|false` so the parser round-trips them.
  const text = typeof value === 'boolean' ? String(value) : cliValue(value, maxLength);
  return `--${spec.flag}=${text}`;
}

export interface ShepherdCommandRender {
  verb: string;
  /** Positional args + options as `x y --flag=v …` (no leading verb/space). */
  rest: string;
}

/**
 * Render doAction args into the compact CLI-style line the tool-call preview
 * shows. Flags come from the shared OPTION_SPECS table so every rendered line
 * parses back with `parseShepherdCli`. Defaults that were not supplied are
 * intentionally omitted, which keeps options like --scope visible without
 * dumping internal implementation details (paneId, tabId, workspaceId).
 */
export function formatShepherdCommand(
  verb: string,
  options: Record<string, any>,
  expanded = false
): ShepherdCommandRender {
  const displayOptions = omitMaterializedDefaults(verb, options);
  const valueLimit = expanded ? Number.POSITIVE_INFINITY : 80;
  const idLimit = expanded ? Number.POSITIVE_INFINITY : 48;
  const tokens: string[] = [];
  const add = (key: string) => {
    const option = cliOption(key, options[key], valueLimit);
    if (option) tokens.push(option);
  };

  switch (verb) {
    case 'spawn':
      tokens.push(cliValue(displayOptions.agent, valueLimit));
      for (const key of SPAWN_OPTION_KEYS) {
        const option = cliOption(key, displayOptions[key], valueLimit);
        if (option) tokens.push(option);
      }
      break;
    case 'prompt':
      tokens.push(handlePreview(options.id, idLimit));
      if (options.message !== undefined) tokens.push(cliValue(options.message, valueLimit));
      add('timeout');
      break;
    case 'status':
    case 'close':
      tokens.push(handlePreview(options.id, idLimit));
      break;
    case 'agents':
      add('agentScope');
      break;
    case 'read':
      tokens.push(cliValue(options.name, valueLimit));
      for (const key of READ_OPTION_KEYS) add(key);
      break;
  }

  return { verb, rest: tokens.join(' ') };
}

/**
 * OpenCode server plugin entry (spec 013, Phase 3).
 *
 * Registers the Shepherd tool family and the `/shepherd` command against
 * the shared engine: spawn/delegate/message/watch/status/read/close plus
 * the herd/agents/prune umbrella, with the child shepherd_message and
 * shepherd_done tools served from the same surface (sheep sessions are
 * gated out of the parent tools, parent sessions out of shepherd_done).
 * Parent fieldnotes sessions resolve onto the shared `.shepherd/sessions`
 * layout (Phase 4); settings are file-based for now (see the carried-forward
 * spec question).
 */

import { Plugin } from "@opencode/plugin"
import { installOpencodeHost } from "./host.ts"
import {
  closeSheep,
  delegateSheep,
  listAgents,
  listHerd,
  messageSheep,
  pruneRegistrations,
  readSheep,
  sheepDone,
  sheepMessage,
  spawnSheep,
  statusSheep,
  watchSheep,
  type OpencodeActionContext,
} from "./actions.ts"
import { installOpencodeBridges, isSheepSession, markParentSession } from "./bridge.ts"
import { manualSpawnArgs, parseShepherdCli, tokenizeCli } from "../extension/cli.ts"
import { displayCommandOutput } from "./display.ts"
import { migrationNoticeOnce } from "../core/migration.ts"
import { noticeNewOrphans, reapOrphans } from "./orphans.ts"

installOpencodeHost()

/** Resolve the OpenCode session's working directory for engine calls. */
async function actionContext(ctx: any, sessionID: string): Promise<OpencodeActionContext> {
  try {
    const session = await ctx.session.get({ sessionID })
    const directory = (session as any)?.directory
    if (typeof directory === "string" && directory.length > 0) return { cwd: directory, sessionId: sessionID }
  } catch {
    // Fall through to the plugin location, then the process cwd.
  }
  return { cwd: ctx.location?.directory ?? process.cwd(), sessionId: sessionID }
}

function errorText(error: unknown): string {
  return error instanceof Error ? error.message : String(error ?? "unknown error")
}

/** Display a human-facing command result without starting an assistant turn. */
async function showCommandOutput(ctx: any, sessionID: string, text: string): Promise<void> {
  // Farewell notice for the old package name: human sessions only, once per
  // host user, and display-only like the rest of the command output.
  if (!isSheepSession(sessionID)) {
    const notice = migrationNoticeOnce()
    if (notice) text = `${notice}\n\n${text}`
  }
  try {
    await displayCommandOutput(ctx, sessionID, text)
  } catch (error) {
    // Never fall back to session.prompt here: that would reintroduce the turn.
    console.error(`shepherd: command display failed: ${errorText(error)}`)
  }
}

/**
 * Gate a parent-only tool: sheep sessions cannot orchestrate. Marks every
 * other caller as a parent session (sheep-only tools refuse those).
 */
function parentOnly(sessionID: string, tool: string): void {
  if (isSheepSession(sessionID)) {
    throw new Error(`${tool} is not available in sheep sessions; sheep use shepherd_message and shepherd_done.`)
  }
  markParentSession(sessionID)
}

const PLACEMENT_DESC =
  "Optional placement: pane_right or pane_down splits the current pane, tab creates a new tab, and workspace creates a new workspace. If omitted, uses a background tab."

export default Plugin.define({
  id: "shepherd",
  async setup(ctx) {
    installOpencodeBridges(ctx)
    // A reload loses in-memory sheep state but not the owned panes/terminals.
    // Surface them once per orphan set; never block tool registration on it.
    void noticeNewOrphans(ctx)
    await ctx.tool.transform((editor) => {
      editor.add({
        name: "shepherd",
        description:
          "Shepherd control plane: list the live herd (agents in Herdr panes), list available agent definitions, prune stale registrations, or reap sheep orphaned by a server restart. Lifecycle operations are separate tools: shepherd_spawn, shepherd_status, shepherd_read, shepherd_close.",
        input: {
          type: "object",
          properties: {
            action: {
              type: "string",
              enum: ["herd", "agents", "prune", "reap"],
              description:
                "herd: live agents. agents: definitions. prune: drop stale registrations. reap: close sheep orphaned by a server restart.",
            },
            agentScope: {
              type: "string",
              enum: ["user", "project", "both"],
              description: "Which agent-definition directories to use (agents action only).",
            },
          },
          required: ["action"],
          additionalProperties: false,
        },
        execute: async (input: any, context: any) => {
          parentOnly(context.sessionID, "shepherd")
          const actx = await actionContext(ctx, context.sessionID)
          const action = (input as any).action
          if (action === "herd") return { content: await listHerd(actx) }
          if (action === "agents")
            return { content: await listAgents(actx, { agentScope: (input as any).agentScope }) }
          if (action === "reap") return { content: reapOrphans(context.sessionID) }
          return { content: await pruneRegistrations(actx) }
        },
      })

      editor.add({
        name: "shepherd_spawn",
        description:
          "Spawn an idle, persistent agent in a Herdr pane (no task submitted). Provide a short task-specific label (for example: code review). Use shepherd with action agents first if you do not know an exact agent name. The result prints an opaque agent id; pass it to shepherd_status, shepherd_read, or shepherd_close. Never use a pane id where an agent id is expected.",
        input: {
          type: "object",
          properties: {
            agent: {
              type: "string",
              description: "Exact discovered agent name (case-sensitive).",
            },
            label: {
              type: "string",
              description: "Short task-specific label (max 64 characters).",
            },
            placement: { type: "string", description: PLACEMENT_DESC },
            no_parent: {
              type: "boolean",
              description:
                "Herdr app / hc only: launch a separate parentless agent in its own tab instead of a subagent under the caller. Defaults to false. Ignored on the Herdr TUI backend.",
            },
            cwd: {
              type: "string",
              description: "Working directory for the child; defaults to the session cwd.",
            },
          },
          required: ["agent"],
          additionalProperties: false,
        },
        execute: async (input: any, context: any) => {
          parentOnly(context.sessionID, "shepherd_spawn")
          const actx = await actionContext(ctx, context.sessionID)
          return {
            content: await spawnSheep(actx, {
              agent: String((input as any).agent ?? ""),
              label: String((input as any).label ?? ""),
              placement: (input as any).placement,
              no_parent: (input as any).no_parent,
              cwd: (input as any).cwd,
            }),
          }
        },
      })

      editor.add({
        name: "shepherd_status",
        description:
          "Inspect a spawned agent without focusing or mutating its pane. Reports process state plus the state of its active task (an idle process can own a waiting task).",
        input: {
          type: "object",
          properties: {
            id: {
              type: "string",
              description: "Exact opaque agent id returned by shepherd_spawn. Never a pane id.",
            },
          },
          required: ["id"],
          additionalProperties: false,
        },
        execute: async (input: any, context: any) => {
          parentOnly(context.sessionID, "shepherd_status")
          const actx = await actionContext(ctx, context.sessionID)
          return { content: await statusSheep(actx, { id: String((input as any).id ?? "") }) }
        },
      })

      editor.add({
        name: "shepherd_read",
        description:
          "Read recent terminal output from a spawned agent for diagnostics. Accepts an agent name, pane id, or opaque agent id.",
        input: {
          type: "object",
          properties: {
            name: {
              type: "string",
              description: "Agent name, pane id, or opaque agent id of the target.",
            },
            lines: {
              type: "number",
              description: "Number of recent lines for read (default 40).",
            },
          },
          required: ["name"],
          additionalProperties: false,
        },
        execute: async (input: any, context: any) => {
          parentOnly(context.sessionID, "shepherd_read")
          const actx = await actionContext(ctx, context.sessionID)
          return {
            content: await readSheep(actx, {
              target: String((input as any).name ?? ""),
              lines: (input as any).lines,
            }),
          }
        },
      })

      editor.add({
        name: "shepherd_close",
        description:
          "Close an owned agent and cancel its active task. Only shepherd-created work is closed.",
        input: {
          type: "object",
          properties: {
            id: {
              type: "string",
              description: "Exact opaque agent id returned by shepherd_spawn. Never a pane id.",
            },
          },
          required: ["id"],
          additionalProperties: false,
        },
        execute: async (input: any, context: any) => {
          parentOnly(context.sessionID, "shepherd_close")
          const actx = await actionContext(ctx, context.sessionID)
          return { content: await closeSheep(actx, { id: String((input as any).id ?? "") }) }
        },
      })

      editor.add({
        name: "shepherd_delegate",
        description:
          "Start tracked asynchronous work on a spawned agent and return a task id immediately. The task can span runs; use shepherd_watch to observe terminal completion. Nothing settles until the sheep calls shepherd_done (or the task fails, is cancelled, or times out).",
        input: {
          type: "object",
          properties: {
            target: {
              type: "string",
              description: "Exact opaque agent id returned by shepherd_spawn. Never a pane id.",
            },
            task: { type: "string", description: "Non-empty delegated task description." },
            timeout: {
              type: "number",
              description: "Optional task deadline in minutes (default 60).",
            },
          },
          required: ["target", "task"],
          additionalProperties: false,
        },
        execute: async (input: any, context: any) => {
          parentOnly(context.sessionID, "shepherd_delegate")
          const actx = await actionContext(ctx, context.sessionID)
          return {
            content: await delegateSheep(actx, {
              target: String((input as any).target ?? ""),
              task: String((input as any).task ?? ""),
              timeout: (input as any).timeout,
            }),
          }
        },
      })

      editor.add({
        name: "shepherd_watch",
        description:
          "Register a non-blocking one-shot watcher for task completions. Returns immediately; already-settled tasks are reported inline and pending completions arrive automatically. Accepts one task id or a non-empty array.",
        input: {
          type: "object",
          properties: {
            id: {
              anyOf: [
                { type: "string", description: "Opaque task id returned by shepherd_delegate." },
                {
                  type: "array",
                  items: { type: "string" },
                  minItems: 1,
                  description: "Non-empty array of opaque task ids.",
                },
              ],
            },
          },
          required: ["id"],
          additionalProperties: false,
        },
        execute: async (input: any, context: any) => {
          parentOnly(context.sessionID, "shepherd_watch")
          const actx = await actionContext(ctx, context.sessionID)
          return { content: await watchSheep(actx, { id: (input as any).id }) }
        },
      })

      editor.add({
        name: "shepherd_message",
        description:
          "Send one asynchronous message and return immediately. Parent form: target MUST be the exact opaque sheep agent id from shepherd_spawn; use expectsReply with a taskId to park the task until the reply arrives. Sheep form (delegated sheep sessions only): target parent/shepherd or a peer agent id; set taskId/replyTo from the delivered task text.",
        input: {
          type: "object",
          properties: {
            target: {
              type: "string",
              description:
                "Parent form: exact opaque sheep agent id. Sheep form: parent, shepherd, or a peer agent id.",
            },
            message: { type: "string", description: "Non-empty message content." },
            taskId: { type: "string", description: "Active delegated task id, when this message belongs to a task." },
            threadId: { type: "string", description: "Conversation/thread correlation id." },
            replyTo: { type: "string", description: "Message id of the request being answered." },
            expectsReply: {
              type: "boolean",
              description: "Track this message as a request that expects a reply.",
            },
            delivery: {
              type: "string",
              enum: ["followUp", "steer"],
              description: "Delivery mode; followUp queues passively, steer is for urgent input.",
            },
          },
          required: ["target", "message"],
          additionalProperties: false,
        },
        execute: async (input: any, context: any) => {
          const actx = await actionContext(ctx, context.sessionID)
          const args = {
            target: String((input as any).target ?? ""),
            message: String((input as any).message ?? ""),
            taskId: (input as any).taskId,
            threadId: (input as any).threadId,
            replyTo: (input as any).replyTo,
            expectsReply: (input as any).expectsReply,
            delivery: (input as any).delivery,
          }
          if (isSheepSession(context.sessionID)) {
            const result = await sheepMessage(actx, args, context.sessionID)
            if (result.parentPrompt && result.parentSessionId) {
              try {
                await ctx.session.prompt({ sessionID: result.parentSessionId, text: result.parentPrompt })
              } catch {
                result.text += " (parent notice delivery failed; the message itself was accepted)"
              }
            }
            return { content: result.text }
          }
          markParentSession(context.sessionID)
          return { content: await messageSheep(actx, args) }
        },
      })

      editor.add({
        name: "shepherd_done",
        description:
          "Sheep-only: explicitly complete, block, or fail the current delegated task. This is the only signal that tells the parent a tracked task has finished. Include the Task ID from the delegated task text.",
        input: {
          type: "object",
          properties: {
            taskId: {
              type: "string",
              description: "Exact Task ID from the delegated task text (omit only to complete the sheep's open task).",
            },
            status: {
              type: "string",
              enum: ["completed", "blocked", "failed"],
              description: "Terminal status for the delegated task.",
            },
            summary: {
              type: "string",
              description: "Concise completion, blocked, or failure summary.",
            },
          },
          required: ["status"],
          additionalProperties: false,
        },
        execute: async (input: any, context: any) => {
          const actx = await actionContext(ctx, context.sessionID)
          const result = await sheepDone(
            actx,
            {
              taskId: (input as any).taskId,
              status: String((input as any).status ?? ""),
              summary: (input as any).summary,
            },
            context.sessionID
          )
          return { content: result.text }
        },
      })
    })

    await ctx.command.transform((editor) => {
      editor.add({
        name: "shepherd",
        description: "Shepherd: agents | herd | spawn <agent> | status <target> | read <target>",
        execute: async ({ sessionID, prompt }: any) => {
          markParentSession(sessionID)
          const actx = await actionContext(ctx, sessionID)
          const raw = String(prompt?.text ?? "").trim()
          if (!raw) {
            await showCommandOutput(
              ctx,
              sessionID,
              [
                "Shepherd settings are file-based in Phase 2: edit the user config or the",
                "project `.shepherd/config.json` directly. For herd operations use one of:",
                "agents, herd, spawn <agent>, status <target>, read <target>.",
              ].join("\n")
            )
            return
          }
          const parsed = parseShepherdCli(tokenizeCli(raw))
          if ("error" in parsed) {
            await showCommandOutput(ctx, sessionID, `Shepherd: ${parsed.error}`)
            return
          }
          try {
            const args = parsed.args as any
            let result: string
            switch (parsed.action) {
              case "herd":
                result = await listHerd(actx)
                break
              case "agents":
                result = await listAgents(actx, { agentScope: args.agentScope })
                break
              case "spawn": {
                // Manual /shepherd spawn means a separate agent (T012), just
                // like Pi's command path: force no_parent even though the bare
                // shepherd_spawn tool defaults to a subagent.
                const spawnArgs = manualSpawnArgs(args)
                result = await spawnSheep(actx, {
                  agent: String(spawnArgs.agent),
                  label: String(spawnArgs.label ?? ""),
                  placement: spawnArgs.placement as string | undefined,
                  cwd: spawnArgs.cwd as string | undefined,
                  no_parent: spawnArgs.no_parent === true,
                })
                break
              }
              case "status":
                result = await statusSheep(actx, { id: args.id })
                break
              case "read":
                result = await readSheep(actx, { target: args.name, lines: args.lines })
                break
              default:
                result = `Shepherd: action "${parsed.action}" is not available from the command yet; use the shepherd_* tools.`
            }
            await showCommandOutput(ctx, sessionID, `[shepherd ${parsed.action}]\n${result}`)
          } catch (error) {
            await showCommandOutput(ctx, sessionID, `Shepherd command failed: ${errorText(error)}`)
          }
        },
      })
    })
  },
})
